{"command":"cd /home/runner/work/flutter_agent_harness/flutter_agent_harness; python3 - <<'EOF'
import json, re, subprocess
base = json.load(open('.crap-baseline.json'))
baselined = {(e['file'], e['line']) for e in base['violations'] if e['gate']=='duplication'}
# re-run and parse WARN section
out = open('/tmp/full_ci_like.log').read()
in_dup = False
cur = None
found = []
for line in out.splitlines():
    if line.startswith('[WARN] duplication'):
        in_dup = True; continue
    if in_dup:
        m = re.match(r'  (\S+):(\d+):', line)
        if m:
            if (m.group(1), int(m.group(2))) not in baselined:
                found.append((m.group(1), int(m.group(2)), line.strip()[:110]))
        elif line.startswith('['):
            in_dup = False
print("unbaselined duplication findings:", len(found))
for f in found: print(" ", f)
EOF"}

